mapper.select:
SELECT COUNT(*) FROM TOOL_INFO WHERE STATUS = 'AVAILABLE'

    AND (TOOL_CODE like '%'||#{keyword}||'%' OR TOOL_NAME like '%'||#{keyword}||'%')


    AND TOOL_TYPE = #{toolType}

SELECT ID, TOOL_CODE, TOOL_NAME, TOOL_TYPE, CABINET_NO, STATUS, SPECIFICATION, IMAGE_URL, CREATE_TIME, UPDATE_TIME
FROM TOOL_INFO
WHERE TOOL_CODE = #{toolCode}

mapper.update:
UPDATE TOOL_INFO
TOOL_NAME = #{toolName, jdbcType=VARCHAR}, TOOL_TYPE = #{toolType, jdbcType=VARCHAR}, CABINET_NO = #{cabinetNo, jdbcType=VARCHAR}, STATUS = #{status, jdbcType=VARCHAR}, SPECIFICATION = #{specification, jdbcType=VARCHAR}, IMAGE_URL = #{imageUrl, jdbcType=VARCHAR}, UPDATE_TIME = SYSDATE
WHERE TOOL_CODE = #{toolCode, jdbcType=VARCHAR}

UPDATE TOOL_INFO
SET STATUS = #{status, jdbcType=VARCHAR}, UPDATE_TIME = SYSDATE
WHERE TOOL_CODE = #{toolCode, jdbcType=VARCHAR}
